mapper.update:
UPDATE form
SET name = #{name}, remark = #{code}, conf = #{schemaJson}, update_time = CURRENT_TIMESTAMP
WHERE org_id = #{tenantId} AND id = #{id}

mapper.select:
SELECT id, org_id AS tenant_id, remark AS code, name, 1 AS version, conf AS schema_json
FROM form
WHERE org_id = #{tenantId} AND id = #{id}

SELECT id, org_id AS tenant_id, process_id AS definition_id, user_id AS requester_id,
       business_id AS business_key, status, current_node_key, form AS form_instance_id,
       var_map AS variables_json, start_time AS started_at, end_time AS ended_at
FROM flow_instance
WHERE org_id = #{tenantId} AND user_id = #{requesterId}
AND status = #{status}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id, org_id AS tenant_id, instance_id, node_key, node_name, assignee AS assignee_id,
       assignee_list AS approval_order_json, 0 AS order_index, approve_mode AS approval_mode,
       status, require_comment, comment, start_time AS started_at, end_time AS ended_at
FROM flow_task
WHERE org_id = #{tenantId} AND assignee = #{assigneeId}
AND status = #{status}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id, tenant_id, request_id, command_type, result_id, status, created_at, completed_at
FROM flow_command
WHERE tenant_id = #{tenantId} AND request_id = #{requestId} AND command_type = #{commandType}

mapper.update:
UPDATE flow_command
SET result_id = #{resultId}, status = 'COMPLETED', completed_at = #{completedAt}
WHERE tenant_id = #{tenantId} AND request_id = #{requestId} AND command_type = #{commandType}

UPDATE flow_outbox_event
SET status = 'PROCESSING', attempts = attempts + 1, next_attempt_at = #{lockUntil}
WHERE id = #{id} AND attempts = #{attempts} AND status IN ('PENDING', 'FAILED', 'PROCESSING')

UPDATE flow_outbox_event
SET status = 'FAILED', last_error = #{lastError}, next_attempt_at = #{nextAttemptAt}
WHERE id = #{id} AND status = 'PROCESSING'
